package vaultor.linked;

import java.io.*;import java.lang.foreign.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.util.*;
import static java.lang.foreign.ValueLayout.*;

/** Rejected/partial candidates and actual metadata observations; no host route. */
public final class PublicationCandidates extends SafetyTests {
    static final List<String> observations=new ArrayList<>();
    static Path fixture()throws IOException{return Files.createTempDirectory(Path.of("native/linked-markdown/.scratch"),"g3b-candidate-").toAbsolutePath();}
    static int replace(Path old,Path stage,Path backup)throws IOException{
        try(var a=Arena.ofConfined()){var result=NativeFiles.invoke("ReplaceFileW",FunctionDescriptor.of(JAVA_INT,ADDRESS,ADDRESS,ADDRESS,JAVA_INT,ADDRESS,ADDRESS),NativeFiles.wide(a,old.toString()),NativeFiles.wide(a,stage.toString()),NativeFiles.wide(a,backup.toString()),0,MemorySegment.NULL,MemorySegment.NULL);return (int)result.value()!=0?0:result.error();}
    }
    static String identity(Path file)throws IOException{try(var h=NativeFiles.open(file,NativeFiles.READ,7,3,false)){return NativeFiles.info(h).identity();}}
    static void compress(Path file)throws IOException{try(var h=NativeFiles.open(file,NativeFiles.READ|NativeFiles.WRITE,7,3,false);var a=Arena.ofConfined()){var format=a.allocate(JAVA_SHORT);format.set(JAVA_SHORT,0,(short)2);var count=a.allocate(JAVA_INT);NativeFiles.yes("CompressFixture",NativeFiles.invoke("DeviceIoControl",FunctionDescriptor.of(JAVA_INT,ADDRESS,JAVA_INT,ADDRESS,JAVA_INT,ADDRESS,JAVA_INT,ADDRESS,ADDRESS),h.value,0x9c040,format,2,MemorySegment.NULL,0,count,MemorySegment.NULL));}}
    static Map<String,String> metadata(Path file)throws IOException {
        var result=new LinkedHashMap<String,String>();var basic=Files.readAttributes(file,BasicFileAttributes.class);result.put("creation",basic.creationTime().toString());result.put("modified",basic.lastModifiedTime().toString());result.put("access",basic.lastAccessTime().toString());
        try(var h=NativeFiles.open(file,NativeFiles.READ,7,3,false);var a=Arena.ofConfined()){
            result.put("attributes",Integer.toHexString(NativeFiles.info(h).attributes()));var owner=a.allocate(ADDRESS);var group=a.allocate(ADDRESS);var dacl=a.allocate(ADDRESS);var label=a.allocate(ADDRESS);var sd=a.allocate(ADDRESS);
            int status=(int)NativeFiles.invoke("GetSecurityInfo",FunctionDescriptor.of(JAVA_INT,ADDRESS,JAVA_INT,JAVA_INT,ADDRESS,ADDRESS,ADDRESS,ADDRESS,ADDRESS),h.value,1,0x17,owner,group,dacl,label,sd).value();if(status!=0)throw new IOException("AUDIT_SECURITY:"+status);
            try{result.put("owner",LinkedStore.hash(MetadataAudit.sid(owner.get(ADDRESS,0))));result.put("group",LinkedStore.hash(MetadataAudit.sid(group.get(ADDRESS,0))));result.put("DACL",LinkedStore.hash(MetadataAudit.acl(dacl.get(ADDRESS,0))));result.put("label",LinkedStore.hash(MetadataAudit.acl(label.get(ADDRESS,0))));result.put("DACL-protected",Boolean.toString(NativeFiles.security(h).protectedDacl()));}finally{NativeFiles.invoke("LocalFree",FunctionDescriptor.of(ADDRESS,ADDRESS),sd.get(ADDRESS,0));}
            try{ReplacementMetadata.requireFullSecurityInspection(h);}catch(IOException e){result.put("full-SACL",e.getMessage());}
            try(var parent=NativeFiles.pin(file.getParent());var full=ReplacementMetadata.sourceLease(parent.handle(),file.getFileName().toString(),true)){try{ReplacementMetadata.requireFullSecurityInspection(full);}catch(IOException e){result.put("SACL-access",e.getMessage());}}catch(IOException e){result.put("SACL-access",e.getMessage());}
        }
        try{result.put("EA",MetadataAudit.ea(file));}catch(IOException e){result.put("EA",e.getMessage());}try{result.put("ADS",NamedStreamProbe.access(file+":fixture",null));}catch(IOException e){result.put("ADS",e.getMessage());}return result;
    }
    static void renameOverwrite(NativeFiles.Handle stage,NativeFiles.Handle directory,String name)throws IOException{
        renameOverwrite(stage,directory,name,false);
    }
    static void renameOverwrite(NativeFiles.Handle stage,NativeFiles.Handle directory,String name,boolean posix)throws IOException{byte[] encoded=name.getBytes(java.nio.charset.StandardCharsets.UTF_16LE);try(var a=Arena.ofConfined()){var data=a.allocate(24+encoded.length,8);data.set(JAVA_INT,0,posix?3:1);data.set(ADDRESS,8,directory.value);data.set(JAVA_INT,16,encoded.length);MemorySegment.copy(encoded,0,data,JAVA_BYTE,20,encoded.length);var io=a.allocate(16,8);int status=(int)NativeFiles.invoke("NtSetInformationFile",FunctionDescriptor.of(JAVA_INT,ADDRESS,ADDRESS,ADDRESS,JAVA_INT,JAVA_INT),stage.value,io,data,(int)data.byteSize(),posix?65:10).value();if(status!=0)throw new IOException("RAW_RENAME:"+Integer.toUnsignedString(status,16));}}
    public static void main(String[] args)throws Exception {
        check("ReplaceFileW backup leaves old hardlink content B and publishes a different inode",()->{
            Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md"),backup=dir.resolve("backup.md"),alias=dir.resolve("alias.md");Files.writeString(source,"Base");Files.writeString(stage,"Local");Files.createLink(alias,source);String stagedId=identity(stage);var before=metadata(source);
            try(var pins=NativeFiles.pin(dir)){require(replace(source,stage,backup)==0);}require(Files.readString(source).equals("Local"));require(Files.readString(alias).equals("Base"));require(Files.readString(backup).equals("Base"));require(identity(source).substring(0,identity(source).lastIndexOf(':')).equals(stagedId.substring(0,stagedId.lastIndexOf(':'))));var after=metadata(source);var aliasAfter=metadata(alias);observations.add("ReplaceFileW ordinary before="+before+" after="+after+" alias="+aliasAfter);
        });
        check("ReplaceFileW retains actually displaced external revision but is not comparison CAS",()->{Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md"),backup=dir.resolve("backup.md");Files.writeString(source,"Base");String baseId=identity(source);Files.writeString(stage,"Local");require(external("replace",source,"External between check and replace")==0);require(replace(source,stage,backup)==0);require(Files.readString(backup).equals("External between check and replace"));require(!identity(backup).equals(baseId));observations.add("ReplaceFileW native success despite stale base; backup mismatch requires conflict, not COMMITTED");});
        check("ReplaceFileW metadata including EA and ADS is measured rather than assumed",()->{Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md"),backup=dir.resolve("backup.md");Files.writeString(source,"Base");Files.writeString(stage,"Local");MetadataAudit.setEa(source);NamedStreamProbe.access(source+":fixture","Named stream");var before=metadata(source);require(replace(source,stage,backup)==0);var after=metadata(source);observations.add("ReplaceFileW EA/ADS before="+before+" after="+after+" backup="+metadata(backup));require(Files.readString(backup).equals("Base"));require(NamedStreamProbe.access(backup+":fixture",null).equals("Named stream"));});
        check("ReplaceFileW sharing failure leaves source and stage intact",()->{Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md"),backup=dir.resolve("backup.md");Files.writeString(source,"Base");Files.writeString(stage,"Local");try(var h=NativeFiles.lease(source,true)){int error=replace(source,stage,backup);require(error!=0);observations.add("ReplaceFileW held source lease error="+error);}require(Files.readString(source).equals("Base"));require(Files.readString(stage).equals("Local"));require(!Files.exists(backup));});
        check("ReplaceFileW existing backup behavior retains observation of all names",()->{Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md"),backup=dir.resolve("backup.md");Files.writeString(source,"Base");Files.writeString(stage,"Local");Files.writeString(backup,"Earlier independent backup");int error=replace(source,stage,backup);observations.add("ReplaceFileW existing backup error="+error+" backup="+Files.readString(backup));require(error!=0||Files.readString(source).equals("Local"));});
        check("raw handle-relative overwrite loses an unseen competing revision and is rejected",()->{for(boolean posix:List.of(false,true)){Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md");Files.writeString(source,"Base");Files.writeString(stage,"Local");require(external("replace",source,"Unseen external")==0);try(var parent=NativeFiles.pin(dir);var h=NativeFiles.open(stage,NativeFiles.READ|NativeFiles.DELETE,1,3,false)){renameOverwrite(h,parent.handle(),"guide.md",posix);}require(Files.readString(source).equals("Local"));require(!Files.exists(stage));observations.add("Raw replacing rename posix="+posix+" retained no displaced external inode: rejected even though confined");}});
        check("inherited-DACL prepublication transfer in private staging is refused",()->{Path dir=fixture(),source=dir.resolve("guide.md"),privateDir=dir.resolve("private");LinkedStore.privateDirectory(privateDir);Path stage=privateDir.resolve("stage.md");Files.writeString(source,"Base");NativeFiles.createFlushed(stage,LinkedStore.utf8("Local"));String before=MetadataAudit.security(source);boolean exact=false;String result="";try(var old=NativeFiles.lease(source,false);var h=NativeFiles.open(stage,NativeFiles.READ|NativeFiles.WRITE|0xc0100,1,3,false)){try{ReplacementMetadata.prepareNew(ReplacementMetadata.observe(old),h);exact=true;}catch(IOException e){result=e.getMessage();}}catch(IOException e){result=e.getMessage();}observations.add("Private inherited-DACL transfer exact="+exact+" result="+result);require(!exact);require(MetadataAudit.security(source).equals(before));require(Files.readString(source).equals("Base"));});
        check("protected-DACL transfer onto a new object is independently measured",()->{Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md");Files.writeString(source,"Base");NativeFiles.createFlushed(stage,LinkedStore.utf8("Local"));try(var old=NativeFiles.open(source,NativeFiles.READ|0x40000,7,3,false)){ReplacementMetadata.protectPrivateStage(old);}String before=MetadataAudit.security(source);try(var old=NativeFiles.lease(source,false);var h=NativeFiles.open(stage,NativeFiles.READ|NativeFiles.WRITE|0xc0100,1,3,false)){ReplacementMetadata.prepareNew(ReplacementMetadata.observe(old),h);}require(MetadataAudit.security(source).equals(before));require(MetadataAudit.security(stage).equals(before));observations.add("Protected-DACL transfer observed exact owner/group/DACL/label, creation and ordinary flags; SACL still unqualified");});
        check("real NTFS compression preservation by ReplaceFileW is measured",()->{Path dir=fixture(),source=dir.resolve("guide.md"),stage=dir.resolve("stage.md"),backup=dir.resolve("backup.md");Files.writeString(source,"Base");compress(source);require((NativeFiles.attributes(source).attributes()&0x800)!=0);Files.writeString(stage,"Local");int result=replace(source,stage,backup);observations.add("Compressed ReplaceFileW result="+result+" source-attributes="+Integer.toHexString(NativeFiles.attributes(source).attributes()));require(result==0);require((NativeFiles.attributes(source).attributes()&0x800)!=0);require(Files.readString(source).equals("Local"));});
        Path evidence=Path.of("native/linked-markdown/evidence/g3b");Files.createDirectories(evidence);Files.writeString(evidence.resolve("candidate-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");Files.writeString(evidence.resolve("candidate-observations.txt"),String.join("\n",observations)+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
}
